import { createContext, useContext } from 'react';
import type { SavedScript } from '@/lib/storage';

export type ScriptsContextType = {
  scripts: SavedScript[];
  name: string;
  setName: (name: string) => void;
  activeId: string | null;
  dirty: boolean;
  save: () => void;
  open: (name: string, source: string, scriptId?: string | null) => void;
  remove: (id: string) => void;
  newScript: () => void;
  lastSavedAt: number | null;
};

export const ScriptsContext = createContext<ScriptsContextType | undefined>(undefined);

export function useScripts() {
  const context = useContext(ScriptsContext);
  if (!context) throw new Error('useScripts must be used inside ScriptsProvider');
  return context;
}
